macro_rules! load { ($name:ident, $directory:literal, $derive:expr) => { fn $name() -> usize { let bytes = include_bytes!(concat!("../specific/", $directory, ".bin")); let derive: fn(&[u8], &[u8]) -> usize = $derive; derive(bytes, bytes) } }; }
load!(binary, "payload", |a, b| a.len() + b.len());
pub fn main() { println!("{}", binary()); }

