macro_rules! load { ($name:ident, $stem:literal, $suffix:literal, $flag:expr) => { fn $name() -> (&'static str, bool) { (include_str!(concat!("../specific/", $stem, $suffix)), $flag) } }; }
load!(first, "one", ".txt", true);
load!(second, "two", ".txt", false);
pub fn main() { println!("{} {} {} {}", first().0, first().1, second().0, second().1); }

macro_rules! load { ($path:literal, $flag:expr) => { (include_str!($path), $flag) }; }
mod nested { pub fn read() -> (&'static str, bool) { load!("../specific/input.txt", true) } }
pub fn main() { let (text, flag) = nested::read(); println!("{} {}", text, flag); }

macro_rules! load { ($path:literal) => { #[test] fn retained_input() { assert_eq!(include_str!($path), "specific-input"); } }; }
load!("../specific/input.txt");
